contract InvMutTest {
    C c;

    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount, address recipient, address recipient2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance");
        require(c.owner() == address(this), "test contract must own c");

        c.withdrawAll(recipient); if (__ESBMC_reverted()) return;

        uint256 cBalBefore = address(c).balance;
        uint256 recipient2BalBefore = recipient2.balance;

        bool reverted;
        c.withdrawAll(recipient2); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            !reverted &&
            address(c).balance == cBalBefore &&
            recipient2.balance == recipient2BalBefore
        );
    }

    receive() external payable {}
}

