// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Phishable c;

    function setUp() public {
        c = new Phishable(address(this));
    }

    function _run(uint256 amount, address recipient, address recipient2) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        vm.assume(c.owner() == address(this));
        try c.withdrawAll(recipient) {} catch { return; }
        uint256 cBalBefore = address(c).balance;
        uint256 recipient2BalBefore = recipient2.balance;
        bool reverted;
        try c.withdrawAll(recipient2) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted &&
            address(c).balance == cBalBefore &&
            recipient2.balance == recipient2BalBefore);
    }

    function testFuzz_run(uint256 amount, address recipient, address recipient2) public {
        vm.assume(recipient.code.length == 0 && uint160(recipient) > 0xffff && recipient != address(this) && recipient != address(c) && recipient != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && recipient != 0x000000000000000000636F6e736F6c652e6c6f67 && recipient != 0x4e59b44847b379578588920cA78FbF26c0B4956C && recipient != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(recipient2.code.length == 0 && uint160(recipient2) > 0xffff && recipient2 != address(this) && recipient2 != address(c) && recipient2 != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && recipient2 != 0x000000000000000000636F6e736F6c652e6c6f67 && recipient2 != 0x4e59b44847b379578588920cA78FbF26c0B4956C && recipient2 != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(amount, recipient, recipient2);
    }

    receive() external payable {}
}
